package com.oms.order.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.GiftRules.map;
import static org.junit.jupiter.api.Assertions.*;

class GiftProductsTest {
    Map<String,Object> kit(String mode){return map("sku_sn","KIT","goods_name","赠送套装","is_gift",1,"is_package",1,"is_fd",0,"bundle",map("revision",3,"enabled",1,"inventory_mode",mode,"components",Arrays.asList(map("sku_sn","A","quantity",2),map("sku_sn","B","quantity",1))));}
    List<Map<String,Object>> parent(Map<String,Object> goods,int quantity){return GiftProducts.freeze(Collections.singletonList(map("sku_sn","KIT","quantity",quantity,"payment",java.math.BigDecimal.ZERO,"platform_oid","")),Collections.singletonMap("KIT",goods),12);}
    @Test void virtualGiftHasParentUnitsAndSeparatePhysicalQuantities(){List<Map<String,Object>> parents=parent(kit("VIRTUAL"),2),lines=GiftProducts.expand(parents);assertEquals("套",GiftProducts.unit(parents.get(0)));assertEquals(4,number(lines.get(0),"quantity"));assertEquals(2,number(lines.get(1),"quantity"));assertEquals(2,number(lines.get(0),"component_quantity"));assertEquals("",lines.get(0).get("platform_oid"));assertEquals("GIFT:12:1",lines.get(0).get("stock_reference"));assertEquals(java.math.BigDecimal.ZERO,lines.get(0).get("payment"));Map<String,Long> remaining=GiftProducts.physicalEntitlement(parents,Collections.singletonList(map("sku_sn","KIT","quantity",1)));assertEquals(2,remaining.get("GIFT:12:1/A"));assertEquals(1,remaining.get("GIFT:12:1/B"));}
    @Test void stockedGiftOnlyConsumesFinishedStock(){List<Map<String,Object>> lines=GiftProducts.expand(parent(kit("STOCKED"),2));assertEquals(1,lines.size());assertEquals("KIT",lines.get(0).get("sku_sn"));assertNotNull(lines.get(0).get("stocked_bundle_snapshot"));assertEquals(2,number(lines.get(0),"quantity"));}
    @Test void overlappingPhysicalSkusKeepIndependentGiftParentSources(){Map<String,Object> normal=map("sku_sn","A","is_gift",1,"goods_name","单件赠品");Map<String,Map<String,Object>> products=new HashMap<>();products.put("A",normal);products.put("KIT",kit("VIRTUAL"));List<Map<String,Object>> parents=GiftProducts.freeze(Arrays.asList(map("sku_sn","A","quantity",1,"platform_oid",""),map("sku_sn","KIT","quantity",1,"platform_oid","")),products,12),lines=GiftProducts.expand(parents);assertEquals(3,lines.size());assertNotEquals(GiftProducts.key(lines.get(0)),GiftProducts.key(lines.get(1)));}
    @Test void luckyRecoveryUsesFrozenUnitsRatherThanDrawingAgain(){Map<String,Object> snapshot=map("business_type","LUCKY_BAG","quantity",2,"units",Arrays.asList(map("unit_id",10,"components",Arrays.asList(map("sku_sn","A","quantity",1),map("sku_sn","D","quantity",1))),map("unit_id",11,"components",Arrays.asList(map("sku_sn","B","quantity",1),map("sku_sn","D","quantity",1)))));Map<String,Object> parent=map("sku_sn","FD","quantity",2,"stock_reference","GIFT:12:2","bundle_snapshot",snapshot);Map<String,Long> keep=GiftProducts.physicalEntitlement(Collections.singletonList(parent),Collections.singletonList(map("sku_sn","FD","quantity",1)));assertEquals(1,keep.get("GIFT:12:2/A"));assertEquals(1,keep.get("GIFT:12:2/D"));assertFalse(keep.containsKey("GIFT:12:2/B"));assertEquals("袋",GiftProducts.unit(parent));}
    @Test void unavailableConfigurationsAndConflictingTypesAreRejected(){Map<String,Object> product=kit("VIRTUAL");product.put("is_fd",1);assertThrows(IllegalArgumentException.class,()->GiftProducts.definition("KIT",product));product.put("is_fd",0);product.put("is_gift",0);assertThrows(IllegalArgumentException.class,()->GiftProducts.definition("KIT",product));product.put("is_gift",1);product.put("bundle",map("enabled",0));assertThrows(IllegalArgumentException.class,()->GiftProducts.definition("KIT",product));}
}
